<?php
require_once __DIR__.'/../includes/auth.php';auth_require();require_once __DIR__.'/../includes/listing.php';$error='';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{$name=trim((string)($_POST['name']??''));if($name===''||mb_strlen($name)>150)throw new InvalidArgumentException('Enter a valid supplier name.');$id=(int)($_POST['supplier_id']??0);domain_require('suppliers.'.($id?'edit':'create'));$values=[$name,mb_substr((string)($_POST['phone']??''),0,30),mb_substr((string)($_POST['address']??''),0,1000),mb_substr((string)($_POST['notes']??''),0,1000)];if($id){$q=$pdo->prepare('SELECT id FROM suppliers WHERE id=? AND shop_id=?');$q->execute([$id,shop_id()]);if(!$q->fetchColumn())throw new RuntimeException('Supplier not found.',403);$pdo->prepare('UPDATE suppliers SET name=?,phone=?,address=?,notes=? WHERE id=? AND shop_id=?')->execute([...$values,$id,shop_id()]);}else{$pdo->prepare('INSERT INTO suppliers (name,phone,address,notes,shop_id) VALUES (?,?,?,?,?)')->execute([...$values,shop_id()]);$id=(int)$pdo->lastInsertId();}domain_audit('supplier_saved','supplier',$id,['name'=>$name]);redirect(BASE_URL.'modules/suppliers.php');}catch(Throwable $e){http_response_code(422);$error=public_error($e);}
$search=is_string($_GET['q']??null)?mb_substr(trim($_GET['q']),0,100):'';$args=[shop_id()];$where='shop_id=?';if($search!==''){$where.=' AND (name LIKE ? OR phone LIKE ?)';$args[]='%'.$search.'%';$args[]='%'.$search.'%';}$list=listing_state(['name_asc'=>['name ASC,id ASC','Name: A–Z','نام: الف تا ی'],'newest'=>['id DESC','Newest first','تازه‌ترین اول'],'oldest'=>['id ASC','Oldest first','قدیمی‌ترین اول']],'name_asc');$q=$pdo->prepare('SELECT COUNT(*) FROM suppliers WHERE '.$where);$q->execute($args);$list=listing_count($list,(int)$q->fetchColumn());
$pageTitle=__t('Suppliers','عرضه‌کنندگان','عرضه کوونکي');require __DIR__.'/../includes/header.php';?>
<h1><?= sanitize($pageTitle) ?></h1><?php if($error):?><p class="alert alert-danger" role="alert"><?= sanitize($error) ?></p><?php endif ?><section class="card modern-form"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="create_supplier"><div class="form-grid"><?php foreach(['name'=>__t('Name','نام','نوم'),'phone'=>__t('Phone','شمارهٔ تماس','شمېره'),'address'=>__t('Address','آدرس','پته'),'notes'=>__t('Notes','یادداشت','یادښت')] as $k=>$v):?><label><?= $v ?><input class="form-control" name="<?= $k ?>" <?= $k==='name'?'required':'' ?>></label><?php endforeach ?></div><button class="btn btn-primary"><?= __t('Save supplier','ذخیرهٔ عرضه‌کننده','عرضه کوونکی خوندي کړئ') ?></button></form></section>
<form class="card modern-form form-grid" method="get"><label><?= __t('Search name or phone','جستجوی نام یا شماره','نوم یا شمېره ولټوئ') ?><input class="form-control" name="q" value="<?= sanitize($search) ?>"></label><?php listing_fields($list) ?><button class="btn btn-primary"><?= __t('Search','جستجو','لټون') ?></button></form><?php $q=$pdo->prepare('SELECT * FROM suppliers WHERE '.$where.' ORDER BY '.$list['order'].' LIMIT '.$list['size'].' OFFSET '.$list['offset']);$q->execute($args);foreach($q->fetchAll() as $s):?><section class="card modern-form"><h2><?= sanitize($s['name']) ?> #<?= (int)$s['id'] ?></h2><p><?= sanitize($s['phone']) ?></p><table class="table"><thead><tr><?php foreach([__t('Purchase','خرید','پېرود'),__t('Date','تاریخ','نېټه'),__t('Total','مجموع','ټول'),__t('Paid','پرداخت','ورکړل'),__t('Returned','برگشت','ستنول'),__t('Payable','بدهی','پور'),__t('Refund due','طلب برگشت پول','د ستنولو طلب')] as $v):?><th><?= $v ?></th><?php endforeach ?></tr></thead><tbody><?php $q2=$pdo->prepare("SELECT p.*,(SELECT COALESCE(SUM(t.amount),0) FROM fund_transactions t WHERE t.shop_id=p.shop_id AND t.source_type='purchase' AND t.source_id=p.id AND t.direction='out') AS paid,(SELECT COALESCE(SUM(r.total_amount),0) FROM purchase_returns r WHERE r.shop_id=p.shop_id AND r.purchase_id=p.id) AS returned,(SELECT COALESCE(SUM(t.amount),0) FROM fund_transactions t WHERE t.shop_id=p.shop_id AND t.source_type='supplier_refund' AND t.source_id=p.id AND t.direction='in') AS refund_received FROM inventory_purchases p WHERE p.shop_id=? AND p.supplier_id=? ORDER BY p.id DESC LIMIT 100");$q2->execute([shop_id(),$s['id']]);foreach($q2->fetchAll() as $p):?><tr><td><a href="purchases.php?id=<?= (int)$p['id'] ?>"><?= sanitize($p['reference']) ?></a></td><td><?= sanitize($p['purchase_date']) ?></td><td><?= sanitize($p['total_amount'].' '.$p['currency_code']) ?></td><td><?= sanitize($p['paid']) ?></td><td><?= sanitize($p['returned']) ?></td><td><?= sanitize(dec_units(dec_sub(dec_sub($p['total_amount'],$p['returned']),$p['paid']))>0?dec_sub(dec_sub($p['total_amount'],$p['returned']),$p['paid']):'0.00') ?></td><td><?= sanitize(dec_units(dec_sub(dec_add($p['paid'],$p['returned']),dec_add($p['total_amount'],$p['refund_received'])))>0?dec_sub(dec_add($p['paid'],$p['returned']),dec_add($p['total_amount'],$p['refund_received'])):'0.00') ?></td></tr><?php endforeach ?></tbody></table><details><summary><?= __t('Edit supplier','تغییر مشخصات عرضه‌کننده','عرضه کوونکی سمول') ?></summary><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="edit_supplier"><input type="hidden" name="supplier_id" value="<?= (int)$s['id'] ?>"><div class="form-grid"><?php foreach(['name'=>__t('Name','نام','نوم'),'phone'=>__t('Phone','شمارهٔ تماس','شمېره'),'address'=>__t('Address','آدرس','پته'),'notes'=>__t('Notes','یادداشت','یادښت')] as $k=>$label):?><label><?= $label ?><input class="form-control" name="<?= $k ?>" value="<?= sanitize($s[$k]??'') ?>" <?= $k==='name'?'required':'' ?>></label><?php endforeach ?></div><button class="btn btn-primary"><?= __t('Save changes','ذخیرهٔ تغییرات','بدلونونه وساتئ') ?></button></form></details></section><?php endforeach ?>
<?php listing_footer($list);require __DIR__.'/../includes/footer.php'; ?>
